        source_details: "વર્ગ મૉનિટર સવારે 10 વાગ્યે હાજરી મોકલશે. કૅન્ટીનનો સ્ટાફ 2 મહિના સુધી દરરોજ વધેલા ખોરાકનું વજન કરશે. એક નાના સર્વેમાં વિદ્યાર્થીઓને તેમની મનપસંદ વાનગીઓ પૂછાશે.",
