        model_reason: "કેટલું ખવાશે તે ઘણી બાબતો પર એકસાથે આધાર રાખે છે (વાર, મેનૂ, હાજરી, હવામાન). તેના નિયમો લખવા અઘરા છે, પણ શીખવા માટે અમારી પાસે ડેટા છે.",
