        success: "મોટાભાગના દિવસે અંદાજ સાચી માત્રાથી 2 kg ની અંદર હોય, અને એક મહિનામાં બગાડ અડધો થાય.",
        error_cost: "અંદાજ ઓછો આવે તો કેટલાક વિદ્યાર્થીઓ ભૂખ્યા રહે, જે વધુ ખરાબ છે. તેથી સલામતી માટે અમે હંમેશાં 5% વધુ ખોરાક બનાવીશું.",
        deploy_how: "કૅન્ટીનના કમ્પ્યુટર પરની એક સરળ સ્પ્રેડશીટ દરરોજ બપોરે બીજા દિવસની દરેક વાનગીની માત્રા બતાવશે.",
        deploy_care: "કૅન્ટીનના ઇન્ચાર્જ રોજનો ડેટા ભરશે. અમારી ટીમ દર મહિને પરિણામ તપાસશે અને મૉડલને ફરીથી શીખવશે.",
        eth_privacy: "અમે ફક્ત વિદ્યાર્થીઓની ગણતરી કરીએ છીએ, કોઈનું નામ લખતા નથી. સર્વેમાં નામ પૂછાતું નથી.",
        eth_bias: "અમે ભોજનની બંને પાળી અને અઠવાડિયાના બધા દિવસો લીધા, જેથી વિદ્યાર્થીઓનું કોઈ જૂથ બાકાત ન રહે.",
