        where: "స్కూల్ క్యాంటీన్‌లో మధ్యాహ్న భోజన సమయంలో, ముఖ్యంగా హాజరు తక్కువ ఉన్న, పరీక్షలు ఉన్న లేదా భారీ వర్షం పడే రోజుల్లో.",
