        features: "తేదీ, వారంలో రోజు\nమెనూ (వంటకాల పేర్లు)\nహాజరైన విద్యార్థుల సంఖ్య\nఒక్కో వంటకం ఎన్ని kg వండారు\nఎన్ని kg ఆహారం మిగిలింది\nప్రత్యేక రోజు: పరీక్ష, పండుగ లేదా వర్షం",
        source_details: "క్లాస్ మానిటర్లు ఉదయం 10 గంటలకు హాజరు పంపుతారు. క్యాంటీన్ సిబ్బంది 2 నెలల పాటు రోజూ మిగిలిన ఆహారాన్ని తూకం వేస్తారు. ఒక చిన్న సర్వేలో విద్యార్థుల ఇష్టమైన వంటకాలు అడుగుతాం.",
        data_check: "రోజూ ఒకే త్రాసు వాడతాం, ప్రతి ఎంట్రీని ఇద్దరు విద్యార్థులు తనిఖీ చేస్తారు, అన్ని తరగతుల, వారంలో అన్ని రోజుల డేటా తీసుకుంటాం.",
        explore_q: "ఏ వంటకాలు ఎక్కువగా వృథా అవుతాయి? వర్షం లేదా పరీక్షల రోజుల్లో వృథా పెరుగుతుందా? హాజరుతో పాటు వృథా ఎలా మారుతుంది?",
        explore_notes: "3 రోజుల తూకం నమోదు కాలేదు, అందుకే ఆ రోజులను తీసేశాం. రాజ్మా అన్నం అతి తక్కువగా వృథా అవుతుంది, సోమవారం వృథా అత్యధికం.",
        model_reason: "ఎంత ఆహారం తింటారు అనేది చాలా విషయాలపై కలిపి ఆధారపడుతుంది (రోజు, మెనూ, హాజరు, వాతావరణం). నియమాలు రాయడం కష్టం, కానీ నేర్చుకోవడానికి మా దగ్గర డేటా ఉంది.",
        model_how: "ట్రైనింగ్ డేటా: గత 2 నెలల రోజువారీ రికార్డులు. ఇన్‌పుట్: రోజు, వంటకం, హాజరు, ప్రత్యేక రోజు. అవుట్‌పుట్: ఎన్ని kg ఆహారం తింటారు (ఒక సంఖ్య).",
