        deploy_how: "క్యాంటీన్ కంప్యూటర్‌లో ఒక సులభమైన స్ప్రెడ్‌షీట్ ప్రతి మధ్యాహ్నం మరుసటి రోజు ఒక్కో వంటకం మోతాదును చూపిస్తుంది.",
        deploy_care: "క్యాంటీన్ ఇన్‌ఛార్జ్ రోజువారీ డేటా నమోదు చేస్తారు. మా బృందం ప్రతి నెలా ఫలితాలు తనిఖీ చేసి మోడల్‌కు మళ్లీ నేర్పిస్తుంది.",
