        explore_q: "వేసవిలో ప్రతి వారం నీటి మట్టం ఎంత వేగంగా పడిపోతుంది? ఎంత వర్షం పడితే బావి మళ్లీ నిండుతుంది?",
        explore_notes: "మార్చి తర్వాత మట్టం వారానికి సుమారు 0.5 m పడిపోతుంది. బ్యాటరీ అయిపోవడంతో సెన్సార్ 4 రోజులు ఆగిపోయింది.",
        model_reason: "నియమం స్పష్టంగా ఉంది, అందరికీ వివరించడం సులభం, మా దగ్గర డేటా కూడా తక్కువ. తర్వాత చాలా ఏళ్ల డేటా వచ్చాక అభ్యాస మోడల్ ప్రయత్నించవచ్చు.",
        model_how: "బావి మట్టం 3 m కంటే తక్కువగా ఉండి, 10 రోజులు వర్ష సూచన లేకపోతే, నారింజ హెచ్చరిక చూపించు. మట్టం 2 m కంటే తక్కువైతే, ఎరుపు హెచ్చరిక చూపించు.",
        test_plan: "గత 3 వేసవుల డేటాపై నియమాలు వర్తింపజేసి, ట్యాంకర్ రోజుల కంటే ముందే హెచ్చరిక వచ్చిందో లేదో చూస్తాం.",
        success: "గత మూడు వేసవుల్లోనూ నీళ్లు అయిపోవడానికి కనీసం 14 రోజుల ముందే హెచ్చరిక రావాలి.",
        error_cost: "తప్పిపోయిన హెచ్చరిక తప్పుడు హెచ్చరిక కంటే చెడ్డది, అందుకే హెచ్చరిక స్థాయిని కొంచెం ఎక్కువగా ఉంచుతాం.",
        deploy_how: "పంచాయతీ ఆఫీసులో నోటీసు బోర్డు, హెచ్చరిక మారినప్పుడల్లా ప్రతి కుటుంబానికి SMS.",
        deploy_care: "పంచాయతీ కార్యదర్శి ప్రతి వారం సెన్సార్‌ను తనిఖీ చేస్తారు. మేము ప్రతి ఏటా నియమాలను సమీక్షిస్తాం.",
        eth_privacy: "మేము ఏ వ్యక్తిగత డేటానూ సేకరించం. SMS కోసం ఫోన్ నంబర్లు అనుమతితో ఇస్తారు, పంచాయతీ వాటిని సురక్షితంగా ఉంచుతుంది.",
        eth_bias: "హెచ్చరిక SMS ద్వారా, మైక్ ప్రకటన ద్వారా రెండు విధాలుగా వెళ్తుంది, కాబట్టి ఫోన్ లేని కుటుంబాలకూ తెలుస్తుంది.",
        eth_safety: "సెన్సార్ పాడైతే హెచ్చరికలో “డేటా లేదు” అని వస్తుంది, “అంతా బాగుంది” అని కాదు. ప్రతి వారం ఒక వ్యక్తి బావిని తనిఖీ చేస్తారు."
