        cls: "ತರಗತಿ 9-B",
        who: "ಮಧ್ಯಾಹ್ನದ ಬಿಸಿಯೂಟ ಮಾಡುವ ಕ್ಯಾಂಟೀನ್ ಅಡುಗೆಯವರು ಮತ್ತು ಮಧ್ಯಾಹ್ನ ಊಟ ಮಾಡುವ ವಿದ್ಯಾರ್ಥಿಗಳು.",
        who_know: "ಅಡುಗೆಯವರು ಸುಮಾರು 600 ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಅಡುಗೆ ಮಾಡುತ್ತಾರೆ, ಆದರೆ ಎಷ್ಟು ಜನ ಊಟ ಮಾಡುತ್ತಾರೆ ಎಂದು ಮೊದಲೇ ಗೊತ್ತಿರುವುದಿಲ್ಲ. ವಿದ್ಯಾರ್ಥಿಗಳು ಇಷ್ಟವಿಲ್ಲದ ಖಾದ್ಯ ಬಿಟ್ಟುಬಿಡುತ್ತಾರೆ.",
        what: "ಪ್ರತಿದಿನ ತುಂಬಾ ಬೇಯಿಸಿದ ಆಹಾರವನ್ನು ಎಸೆಯಲಾಗುತ್ತಿದೆ.",
        what_evidence: "ನಾವು 2 ವಾರ ಉಳಿದ ಆಹಾರವನ್ನು ತೂಕ ಮಾಡಿದೆವು: ಪ್ರತಿದಿನ ಸುಮಾರು 18 kg ಆಹಾರ ವ್ಯರ್ಥವಾಯಿತು. ಅಡುಗೆಯವರೂ ಇದನ್ನೇ ಹೇಳಿದರು.",
        where: "ಶಾಲಾ ಕ್ಯಾಂಟೀನ್‌ನಲ್ಲಿ ಮಧ್ಯಾಹ್ನದ ಊಟದ ಸಮಯದಲ್ಲಿ, ಮುಖ್ಯವಾಗಿ ಹಾಜರಿ ಕಡಿಮೆ ಇರುವ, ಪರೀಕ್ಷೆ ಇರುವ ಅಥವಾ ಜೋರು ಮಳೆ ಇರುವ ದಿನಗಳಲ್ಲಿ.",
        why_value: "ಪ್ರತಿದಿನ ಪ್ರತಿ ಖಾದ್ಯವನ್ನು ಸರಿಯಾದ ಪ್ರಮಾಣದಲ್ಲಿ ಬೇಯಿಸುವುದು.",
