        features: "ದಿನಾಂಕ ಮತ್ತು ವಾರದ ದಿನ\nಮೆನು (ಖಾದ್ಯಗಳ ಹೆಸರು)\nಹಾಜರಿದ್ದ ವಿದ್ಯಾರ್ಥಿಗಳ ಸಂಖ್ಯೆ\nಪ್ರತಿ ಖಾದ್ಯ ಎಷ್ಟು kg ಬೇಯಿಸಲಾಯಿತು\nಎಷ್ಟು kg ಆಹಾರ ಉಳಿಯಿತು\nವಿಶೇಷ ದಿನ: ಪರೀಕ್ಷೆ, ಹಬ್ಬ ಅಥವಾ ಮಳೆ",
