        data_check: "ಪ್ರತಿದಿನ ಒಂದೇ ತಕ್ಕಡಿ ಬಳಸುತ್ತೇವೆ, ಪ್ರತಿ ನಮೂದನ್ನು ಇಬ್ಬರು ವಿದ್ಯಾರ್ಥಿಗಳು ಪರಿಶೀಲಿಸುತ್ತಾರೆ, ಎಲ್ಲಾ ತರಗತಿಗಳ ಮತ್ತು ವಾರದ ಎಲ್ಲಾ ದಿನಗಳ ಡೇಟಾ ತೆಗೆದುಕೊಳ್ಳುತ್ತೇವೆ.",
        explore_q: "ಯಾವ ಖಾದ್ಯಗಳು ಹೆಚ್ಚು ವ್ಯರ್ಥವಾಗುತ್ತವೆ? ಮಳೆ ಅಥವಾ ಪರೀಕ್ಷೆಯ ದಿನಗಳಲ್ಲಿ ವ್ಯರ್ಥ ಹೆಚ್ಚುತ್ತದೆಯೇ? ಹಾಜರಿಯೊಂದಿಗೆ ವ್ಯರ್ಥ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ?",
        explore_notes: "3 ದಿನಗಳ ತೂಕ ದಾಖಲಾಗಿರಲಿಲ್ಲ, ಅದಕ್ಕೆ ಆ ದಿನಗಳನ್ನು ತೆಗೆದುಹಾಕಿದೆವು. ರಾಜ್ಮಾ ಅನ್ನ ಅತಿ ಕಡಿಮೆ ವ್ಯರ್ಥವಾಗುತ್ತದೆ, ಸೋಮವಾರ ವ್ಯರ್ಥ ಅತಿ ಹೆಚ್ಚು.",
        model_reason: "ಎಷ್ಟು ಆಹಾರ ತಿನ್ನಲಾಗುತ್ತದೆ ಎಂಬುದು ಹಲವು ವಿಷಯಗಳ ಮೇಲೆ ಒಟ್ಟಿಗೆ ಅವಲಂಬಿಸಿದೆ (ದಿನ, ಮೆನು, ಹಾಜರಿ, ಹವಾಮಾನ). ನಿಯಮ ಬರೆಯುವುದು ಕಷ್ಟ, ಆದರೆ ಕಲಿಯಲು ನಮ್ಮ ಬಳಿ ಡೇಟಾ ಇದೆ.",
        model_how: "ತರಬೇತಿ ಡೇಟಾ: ಕಳೆದ 2 ತಿಂಗಳ ದೈನಂದಿನ ದಾಖಲೆಗಳು. ಇನ್‌ಪುಟ್: ದಿನ, ಖಾದ್ಯ, ಹಾಜರಿ, ವಿಶೇಷ ದಿನ. ಔಟ್‌ಪುಟ್: ಎಷ್ಟು kg ಆಹಾರ ತಿನ್ನಲಾಗುತ್ತದೆ (ಒಂದು ಸಂಖ್ಯೆ).",
        test_plan: "ಮೊದಲ 6 ವಾರಗಳ ಡೇಟಾದಿಂದ ಮಾಡೆಲ್‌ಗೆ ಕಲಿಸಿ, ಕೊನೆಯ 2 ವಾರಗಳಲ್ಲಿ ಪರೀಕ್ಷಿಸುತ್ತೇವೆ. ನಂತರ ಅಡುಗೆಯವರು ಒಂದು ವಾರ ಅದನ್ನು ಬಳಸಿ ನೋಡುತ್ತಾರೆ.",
        success: "ಹೆಚ್ಚಿನ ದಿನಗಳಲ್ಲಿ ಊಹೆ ನಿಜ ಪ್ರಮಾಣಕ್ಕಿಂತ 2 kg ಒಳಗಿರಬೇಕು, ಒಂದು ತಿಂಗಳಲ್ಲಿ ವ್ಯರ್ಥ ಅರ್ಧಕ್ಕೆ ಇಳಿಯಬೇಕು.",
        error_cost: "ಊಹೆ ಕಡಿಮೆಯಾದರೆ ಕೆಲವು ವಿದ್ಯಾರ್ಥಿಗಳು ಹಸಿದಿರುತ್ತಾರೆ, ಅದು ಹೆಚ್ಚು ಕೆಟ್ಟದು. ಅದಕ್ಕೆ ಸುರಕ್ಷತೆಗಾಗಿ ಯಾವಾಗಲೂ 5% ಹೆಚ್ಚು ಆಹಾರ ಮಾಡುತ್ತೇವೆ.",
        deploy_how: "ಕ್ಯಾಂಟೀನ್ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಒಂದು ಸರಳ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ಪ್ರತಿ ಮಧ್ಯಾಹ್ನ ಮರುದಿನದ ಪ್ರತಿ ಖಾದ್ಯದ ಪ್ರಮಾಣ ತೋರಿಸುತ್ತದೆ.",
