        eth_privacy: "ನಾವು ವಿದ್ಯಾರ್ಥಿಗಳನ್ನು ಎಣಿಸುತ್ತೇವೆ ಅಷ್ಟೇ, ಯಾರ ಹೆಸರನ್ನೂ ಬರೆಯುವುದಿಲ್ಲ. ಸಮೀಕ್ಷೆಯಲ್ಲಿ ಹೆಸರು ಕೇಳುವುದಿಲ್ಲ.",
        eth_bias: "ಎರಡೂ ಊಟದ ಪಾಳಿಗಳು ಮತ್ತು ವಾರದ ಎಲ್ಲಾ ದಿನಗಳನ್ನು ಸೇರಿಸಿದ್ದೇವೆ, ಹೀಗಾಗಿ ಯಾವ ವಿದ್ಯಾರ್ಥಿ ಗುಂಪೂ ಹೊರಗುಳಿಯುವುದಿಲ್ಲ.",
