        who_know: "ಪ್ರತಿ ಬೇಸಿಗೆಯಲ್ಲಿ ಹಳ್ಳಿಯ ಬಾವಿ ಮತ್ತು ಕೈಪಂಪುಗಳು ಬತ್ತಿಹೋಗುತ್ತವೆ. ಮಹಿಳೆಯರು ಮತ್ತು ಹುಡುಗಿಯರು ದೂರದಿಂದ ನೀರು ತರುತ್ತಾರೆ.",
        what: "ಬೇಸಿಗೆಯಲ್ಲಿ ಇದ್ದಕ್ಕಿದ್ದಂತೆ ನೀರು ಖಾಲಿಯಾಗುತ್ತದೆ ಮತ್ತು ಟ್ಯಾಂಕರ್‌ಗಳು ತಡವಾಗಿ ಬರುತ್ತವೆ.",
        what_evidence: "ಪಂಚಾಯಿತಿ ರಿಜಿಸ್ಟರ್ ಪ್ರಕಾರ ಕಳೆದ ಬೇಸಿಗೆಯಲ್ಲಿ 41 ದಿನ ಟ್ಯಾಂಕರ್ ಬೇಕಾಯಿತು. ಸತತ 2–3 ದಿನ ನೀರು ಸಿಗಲಿಲ್ಲ ಎಂದು ಕುಟುಂಬಗಳು ಹೇಳಿದವು.",
        where: "ಏಪ್ರಿಲ್‌ನಿಂದ ಜೂನ್‌ವರೆಗೆ, ಮಳೆ ಇಲ್ಲದೆ ಅಂತರ್ಜಲ ಮಟ್ಟ ಇಳಿದಾಗ.",
