        why_improve: "ಕುಟುಂಬಗಳು ಮೊದಲೇ ನೀರು ಉಳಿಸಬಹುದು, ಪಂಚಾಯಿತಿ ಸಮಯಕ್ಕೆ ಟ್ಯಾಂಕರ್ ತರಿಸಬಹುದು.",
